pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 b) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);
        b = bound(b, 1, 1e18);

        // lock at block b so the guess block is g = b + 1
        vm.roll(b);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // roll far past g + 256 so blockhash(g) == 0 and the answer is
        // keccak256(bytes32(0)) — a value the test can compute itself
        uint256 g = b + 1;
        vm.roll(g + 257);
        bytes32 winningHash = keccak256(abi.encodePacked(blockhash(g)));

        // lock the winning hash: only possible for the ORIGINAL contract,
        // which still records caller-supplied guesses (new guess cycle)
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningHash);
        vm.roll(g + 258);
        vm.prank(actor);
        c.settle();

        // Rule: the correct contract always pays out its full escrow to the
        // winning guesser, leaving c's balance at 0. The mutant drops the
        // guess hash (stores 0), so settle never matches and the balance
        // remains nonzero.
        assertTrue(address(c).balance == 0);
    }
}

