pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 h1, bytes32 h2) public {
        vm.assume(actor.code.length == 0);
        vm.assume(h2 != bytes32(0));

        // First lock by actor.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h1);

        // Advance past the target block and settle (no payout for arbitrary h1).
        uint256 target = block.number + 1;
        vm.roll(target + 1);
        vm.prank(actor);
        c.settle();

        // After settle the actor may lock again with a fresh hash.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h2);

        // The stored guess always equals the most recently locked hash.
        assertTrue(c.guesses(actor).guess == h2);
    }
}

