pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 hash) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // advance one block so the recorded target block has been mined
        vm.roll(block.number + 1);

        // General rule: exactly one block after lockInGuess, settle() must NOT revert
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

