pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        uint256 blockBefore = block.number;
        vm.deal(actor, 1 ether);

        vm.prank(actor);
        try c.lockInGuess{value: 1 ether}(g) {
            // General rule: a successful lockInGuess in block `blockBefore` must
            // record a target block strictly in the future (blockBefore + 1).
            assertTrue(
                uint256(c.guesses(actor).block) > blockBefore,
                "target block must be strictly after the locking block"
            );
        } catch {
            // For any fresh actor lockInGuess must not revert; if it did, the
            // recorded state stays zero, which also violates the rule.
            assertTrue(uint256(c.guesses(actor).block) > blockBefore);
        }
    }
}

