pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address actor, bytes32 guessHash) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);
        // target block is block.number + 1; we are still at block.number, so settle must revert
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) payable { c = _c; }

    function testFreshLock(bytes32 hash) public payable {
        uint amt = 1 ether;
        require(address(this).balance >= amt);

        bool ok;
        (ok, ) = address(c).call{value: amt}(abi.encodeWithSelector(c.lockInGuess.selector, hash));

        assert(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        require(address(this).balance >= 1 ether);
        bool reverted;
        try c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(block.number))) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

